const clamp01=n=>Math.min(1,Math.max(0,n));
const smoothstep=n=>{const t=clamp01(n);return t*t*(3-2*t)};
let lenis=null;
const desktopScroll=matchMedia('(min-width: 821px) and (hover: hover) and (pointer: fine)');
function configureScroll(){lenis?.stop();lenis?.destroy();lenis=null;if(!motion.matches&&desktopScroll.matches&&window.Lenis){lenis=new Lenis({autoRaf:false,duration:1.25,smoothWheel:true,syncTouch:false,wheelMultiplier:.9,anchors:true,prevent:node=>Boolean(node.closest?.('.project-dialog'))});lenis.on('scroll',()=>{pageDirty=true})}}
const heroScroll=document.querySelector('.hero-scroll'),heroImg=document.querySelector('.hero-image'),heroCopy=document.querySelector('.hero-content');
const sequence=document.querySelector('.drawing-master'),panels=[...sequence.querySelectorAll('.drawing-panel')],sceneButtons=[...document.querySelectorAll('[data-scene-go]')];
const scenes=panels.map(el=>({el,title:el.querySelector('.drawing-title'),photo:el.querySelector('.drawing-photo'),scan:el.querySelector('.scan-line'),bar:el.querySelector('.drawing-status i')}));
// Keep SVG contour sources out of the initial network work on mobile.
new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)return;sequence.querySelectorAll('svg image[data-src]').forEach(image=>{if(!image.hasAttribute('href'))image.setAttribute('href',innerWidth<=820?image.dataset.src.replace('.jpg','-mobile.jpg'):image.dataset.src)})},{rootMargin:'600px'}).observe(sequence);
const interlude=document.querySelector('.interlude'),word=interlude.querySelector('.interlude-word'),parallaxImg=interlude.querySelector('img');
let pageDirty=true,lastScene=-1;
function updatePage(){pageDirty=false;const vh=innerHeight;
if(!motion.matches){const h=heroScroll.getBoundingClientRect();if(h.bottom>0&&h.top<vh){const p=clamp01(-h.top/Math.max(1,h.height-vh));heroImg.style.transform=`scale(${1.04+p*.32})`;heroImg.style.filter=`blur(${p*p*7}px)`;heroImg.style.opacity=String(1-p*.6);heroCopy.style.transform=`translateY(${-p*85}px)`;heroCopy.style.opacity=String(1-clamp01(p*1.5));heroCopy.style.filter=`blur(${p*4}px)`}
const r=sequence.getBoundingClientRect();if(r.bottom>0&&r.top<vh){const t=clamp01(-r.top/Math.max(1,r.height-vh))*3;let nearest=Math.min(2,Math.floor(t));for(let i=0;i<scenes.length;i++){const s=scenes[i],enter=i===0?1:smoothstep((t-i+.14)/.28),exit=i===2?1:1-smoothstep((t-i-.86)/.28),alpha=enter*exit,p=smoothstep((t-i-.12)/.61);s.el.style.opacity=alpha.toFixed(4);s.el.style.zIndex=String(i);s.el.style.visibility=alpha>.001?'visible':'hidden';s.el.setAttribute('aria-hidden',String(alpha<.5));s.title.style.transform=`translateY(${(1-enter)*20-(1-exit)*14}px)`;s.photo.style.clipPath=`inset(0 ${(1-p)*100}% 0 0)`;s.scan.style.left=`${p*100}%`;s.scan.style.opacity=p>0&&p<1?'1':'0';s.bar.style.transform=`scaleX(${p})`}
if(lastScene!==nearest){lastScene=nearest;sceneButtons.forEach((b,i)=>b.setAttribute('aria-current',String(i===nearest)))}}
const r2=interlude.getBoundingClientRect();if(r2.bottom>0&&r2.top<vh){const p=clamp01((vh-r2.top)/(vh+r2.height));word.style.transform=`translateX(${(p-.5)*24}%) translateY(${(1-p)*85}px)`;parallaxImg.style.transform=`translateY(${-p*16}%)`}}
}
sceneButtons.forEach(b=>b.addEventListener('click',()=>{const index=Number(b.dataset.sceneGo),top=sequence.getBoundingClientRect().top+scrollY+(sequence.offsetHeight-innerHeight)*(index+.4)/3;if(lenis)lenis.scrollTo(top,{duration:1.8});else scrollTo({top,behavior:motion.matches?'instant':'smooth'})}));
// Word masks preserve the original text nodes and inline emphasis for assistive tech.
document.querySelectorAll('.intro h2,.section-heading h2,.about h2,.contact-main,.interlude>p').forEach(heading=>{let index=0;const walker=document.createTreeWalker(heading,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())if(walker.currentNode.textContent.trim())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement.closest('.contact-main>span'))continue;const fragment=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(text=>{if(!text.trim()){fragment.append(document.createTextNode(text));return}const clip=document.createElement('span'),inner=document.createElement('span');clip.className='word-clip';inner.className='word-inner';inner.style.setProperty('--word-delay',Math.min(index++*55,650)+'ms');inner.textContent=text;clip.append(inner);fragment.append(clip)});node.replaceWith(fragment)}heading.classList.add('text-entrance')});
const entranceTargets=document.querySelectorAll('.intro-copy p,.intro-strip img,.intro-photo,.portrait,.about-copy>p:not(.eyebrow),.services article,.section-heading>p,.contact-bottom,.filters,.gallery-arrangements,.project,.eyebrow');
entranceTargets.forEach((el,i)=>{el.classList.add('motion-enter');el.style.setProperty('--entrance-delay',((el.matches('.project')?[...el.parentNode.children].indexOf(el)%3:i%3)*100)+'ms');if(el.matches('.intro-photo,.portrait'))el.classList.add('motion-image')});
const entranceObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('motion-arrived','text-arrived','visible');entranceObserver.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('.motion-enter,.text-entrance,.reveal').forEach(el=>entranceObserver.observe(el));

dialog.addEventListener('close',()=>lenis?.start());new MutationObserver(()=>{if(dialog.open)lenis?.stop()}).observe(dialog,{attributes:true,attributeFilter:['open']});
addEventListener('scroll',()=>pageDirty=true,{passive:true});addEventListener('resize',()=>{pageDirty=true});motion.addEventListener('change',()=>{configureScroll();pageDirty=true;scenes.forEach(s=>{s.el.style.visibility='';s.el.removeAttribute('aria-hidden')})});
desktopScroll.addEventListener('change',()=>{configureScroll();pageDirty=true});
let lastTimestamp=0;configureScroll();function tick(time){const dt=Math.min(48,time-lastTimestamp||16);lastTimestamp=time;lenis?.raf(time);if(!lenis&&document.documentElement.classList.contains('lenis'))document.documentElement.classList.remove(...[...document.documentElement.classList].filter(c=>c==='lenis'||c.startsWith('lenis-')));if(pageDirty)updatePage();window.updateOrbit?.(dt,time);requestAnimationFrame(tick)}requestAnimationFrame(tick);
